package fr.formation.clean;
import fr.formation.clean.application.boundary.*; import fr.formation.clean.application.usecase.*; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.annotation.Bean;
@SpringBootApplication public class CleanApplication {public static void main(String[]args){SpringApplication.run(CleanApplication.class,args);}@Bean CreateReservationInputBoundary createReservation(RoomGateway rooms,ReservationGateway reservations,NotificationGateway notifications){return new CreateReservationInteractor(rooms,reservations,notifications);}@Bean CancelReservationInputBoundary cancelReservation(ReservationGateway reservations){return new CancelReservationInteractor(reservations);}@Bean ManageRoomInputBoundary manageRoom(RoomGateway rooms){return new ManageRoomInteractor(rooms);}}
